//! Embedded default contract code registry.
//!
//! The BoC hex strings below are the canonical published artifacts used by the
//! reference TON SDKs. They were transcribed from `nessshon/ton-core`'s
//! `CONTRACT_CODES`, whose jetton contracts derive from
//! `ton-blockchain/token-contract` and whose NFT contracts derive from the
//! TEP-62/TEP-85 reference implementations. They are embedded so callers can
//! compute addresses and build deployment messages offline, without downloading
//! code at runtime. Refer to the upstream repositories for licensing terms.
//!
//! The registry is version-keyed. Wrappers expose `default_code()` and also
//! accept an explicit [`crate::tvm::Cell`] so applications can pin their own
//! audited build.

use std::sync::{Arc, OnceLock};

use crate::tvm::{Cell, TvmError, deserialize_boc};

/// Contract editions with embedded default code.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ContractVersion {
    /// `JettonMasterStandard`.
    JettonMasterStandard,
    /// `JettonMasterStablecoin`.
    JettonMasterStablecoin,
    /// `JettonMasterStablecoinV2`.
    JettonMasterStablecoinV2,
    /// `JettonWalletStandard`.
    JettonWalletStandard,
    /// `JettonWalletStablecoin`.
    JettonWalletStablecoin,
    /// `JettonWalletStablecoinV2`.
    JettonWalletStablecoinV2,
    /// `NFTCollectionStandard`.
    NFTCollectionStandard,
    /// `NFTCollectionEditable`.
    NFTCollectionEditable,
    /// `NFTItemStandard`.
    NFTItemStandard,
    /// `NFTItemEditable`.
    NFTItemEditable,
    /// `NFTItemSoulbound`.
    NFTItemSoulbound,
}

impl ContractVersion {
    /// Every version in the registry.
    pub const ALL: [Self; 11] = [
        Self::JettonMasterStandard,
        Self::JettonMasterStablecoin,
        Self::JettonMasterStablecoinV2,
        Self::JettonWalletStandard,
        Self::JettonWalletStablecoin,
        Self::JettonWalletStablecoinV2,
        Self::NFTCollectionStandard,
        Self::NFTCollectionEditable,
        Self::NFTItemStandard,
        Self::NFTItemEditable,
        Self::NFTItemSoulbound,
    ];

    /// Stable identifier used in documentation and errors.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::JettonMasterStandard => "JettonMasterStandard",
            Self::JettonMasterStablecoin => "JettonMasterStablecoin",
            Self::JettonMasterStablecoinV2 => "JettonMasterStablecoinV2",
            Self::JettonWalletStandard => "JettonWalletStandard",
            Self::JettonWalletStablecoin => "JettonWalletStablecoin",
            Self::JettonWalletStablecoinV2 => "JettonWalletStablecoinV2",
            Self::NFTCollectionStandard => "NFTCollectionStandard",
            Self::NFTCollectionEditable => "NFTCollectionEditable",
            Self::NFTItemStandard => "NFTItemStandard",
            Self::NFTItemEditable => "NFTItemEditable",
            Self::NFTItemSoulbound => "NFTItemSoulbound",
        }
    }

    /// Embedded BoC hex for this version.
    ///
    /// The payload is the contract code cell encoded as a single-root generic
    /// BoC. CRC32C trailers are stripped by [`Self::default_code`] before the
    /// local decoder runs.
    pub const fn code_boc_hex(self) -> &'static str {
        match self {
            Self::JettonMasterStandard => {
                ""
            }
            Self::JettonMasterStablecoin => {
                ""
            }
            Self::JettonMasterStablecoinV2 => {
                ""
            }
            Self::JettonWalletStandard => {
                ""
            }
            Self::JettonWalletStablecoin => {
                "b5ee9c7201010101002300084202ba2918c8947e9b25af9ac1b883357754173e5812f807a3d6e642a14709595395"
            }
            Self::JettonWalletStablecoinV2 => {
                ""
            }
            Self::NFTCollectionStandard => {
                ""
            }
            Self::NFTCollectionEditable => {
                ""
            }
            Self::NFTItemStandard => {
                ""
            }
            Self::NFTItemEditable => {
                ""
            }
            Self::NFTItemSoulbound => {
                ""
            }
        }
    }

    /// Decodes and caches the embedded code cell.
    pub fn default_code(self) -> Result<Arc<Cell>, ContractCodeError> {
        let cached =
            CODE_CACHE[self as usize].get_or_init(|| decode_embedded_boc(self.code_boc_hex()));
        match cached {
            Ok(code) => Ok(code.clone()),
            Err(message) => Err(ContractCodeError::InvalidBoc {
                version: self.as_str(),
                message: message.clone(),
            }),
        }
    }

    /// Returns the cell hash of the embedded code.
    pub fn default_code_hash(self) -> Result<[u8; 32], ContractCodeError> {
        Ok(self.default_code()?.hash())
    }
}

/// Errors returned while decoding embedded contract code.
#[derive(Debug, thiserror::Error)]
pub enum ContractCodeError {
    /// The embedded BoC could not be decoded.
    #[error("failed to decode embedded contract code for {version}: {message}")]
    InvalidBoc {
        /// Version identifier.
        version: &'static str,
        /// Decoder diagnostic.
        message: String,
    },
}

static CODE_CACHE: [OnceLock<Result<Arc<Cell>, String>>; 11] = [const { OnceLock::new() }; 11];

fn decode_embedded_boc(hex: &str) -> Result<Arc<Cell>, String> {
    let mut bytes = hex_decode(hex).map_err(|error| error.to_string())?;
    strip_boc_crc32c(&mut bytes);
    deserialize_boc(&bytes).map_err(|error: TvmError| error.to_string())
}

fn hex_decode(hex: &str) -> Result<Vec<u8>, TvmError> {
    let digits = hex.as_bytes();
    if !digits.len().is_multiple_of(2) {
        return Err(TvmError::Hex(hex::FromHexError::OddLength));
    }
    let mut out = Vec::with_capacity(digits.len() / 2);
    for (index, pair) in digits.as_chunks::<2>().0.iter().enumerate() {
        let hi =
            hex_nibble(pair[0]).ok_or(TvmError::Hex(hex::FromHexError::InvalidHexCharacter {
                c: char::from(pair[0]),
                index,
            }))?;
        let lo =
            hex_nibble(pair[1]).ok_or(TvmError::Hex(hex::FromHexError::InvalidHexCharacter {
                c: char::from(pair[1]),
                index,
            }))?;
        out.push((hi << 4) | lo);
    }
    Ok(out)
}

const fn hex_nibble(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

/// Strips a CRC32C trailer from a generic BoC so the local decoder, which only
/// accepts the plain generic magic, can read it.
fn strip_boc_crc32c(bytes: &mut Vec<u8>) {
    if bytes.len() >= 9 && bytes[0..4] == [0xb5, 0xee, 0x9c, 0x72] && (bytes[4] & 0x40) != 0 {
        bytes[4] &= !0x40;
        bytes.truncate(bytes.len() - 4);
    }
}

#[cfg(test)]
mod tests {
    use super::ContractVersion;

    #[test]
    fn embedded_codes_decode() {
        for version in ContractVersion::ALL {
            let code = version
                .default_code()
                .unwrap_or_else(|error| panic!("{} must decode: {error}", version.as_str()));
            assert!(!code.hash().iter().all(|byte| *byte == 0));
        }
    }
}
